from collections import deque

def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    # Build a trie of the banned strings.
    goto = [{}]
    bad = [False]
    for word in banned:
        node = 0
        for ch in word:
            if ch not in goto[node]:
                goto.append({})
                bad.append(False)
                goto[node][ch] = len(goto) - 1
            node = goto[node][ch]
        bad[node] = True

    # Aho-Corasick: failure links and full transition table.
    m = len(goto)
    fail = [0] * m
    delta = [{} for _ in range(m)]
    queue = deque([0])
    while queue:
        u = queue.popleft()
        for ch in alphabet:
            if ch in goto[u]:
                v = goto[u][ch]
                fail[v] = 0 if u == 0 else delta[fail[u]][ch]
                bad[v] = bad[v] or bad[fail[v]]
                delta[u][ch] = v
                queue.append(v)
            else:
                delta[u][ch] = 0 if u == 0 else delta[fail[u]][ch]

    # Live states: automaton nodes that do not contain any banned string.
    live = [i for i in range(m) if not bad[i]]
    idx = {s: i for i, s in enumerate(live)}
    k = len(live)

    # Transition matrix over live states.
    T = [[0] * k for _ in range(k)]
    for s in live:
        for ch in alphabet:
            t = delta[s][ch]
            if not bad[t]:
                T[idx[s]][idx[t]] += 1

    def mat_mul(A, B):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ci = C[i]
            for t, a in enumerate(A[i]):
                if a:
                    Bt = B[t]
                    for j in range(size):
                        Ci[j] += a * Bt[j]
            for j in range(size):
                Ci[j] %= MOD
        return C

    def vec_mul(v, A):
        size = len(v)
        out = [0] * size
        for i, a in enumerate(v):
            if a:
                Ai = A[i]
                for j in range(size):
                    out[j] += a * Ai[j]
        return [x % MOD for x in out]

    # Start at the root (always live, since banned strings are non-empty).
    vec = [0] * k
    vec[0] = 1
    while n:
        if n & 1:
            vec = vec_mul(vec, T)
        n >>= 1
        if n:
            T = mat_mul(T, T)

    return sum(vec) % MOD
